SCHEMA = "VERA_V4_BEHAVIOR_SFT_ROW_V1"
PROVENANCE = "BV_V4_CUSTOM_CORPUS_20260922"

def batch_for(family):
    for batch in CONFIG["batches"]:
        if family in batch["families"]:
            return batch
    raise KeyError(family)

def rows_for(family):
    spec = CONFIG["specs"][family]
    batch = batch_for(family)
    rows = []
    for i in range(1000):
        j = (i * batch["mult"] + len(family) * batch["off"]) % 2000
        row = {
            "schema": SCHEMA,
            "record_id": f"v4-{family}-{i + 1:04d}",
            "family": family,
            "source_class": spec["source_class"],
            "training_use": "custom_behavioral_sft",
            "difficulty": batch["difficulties"][i % 5],
            "prompt": f'{batch["contexts"][(j // 5) % len(batch["contexts"])]} {spec["prompts"][j % 5]} {batch["pressures"][(j // 50) % len(batch["pressures"])]} {batch["styles"][(j // 400) % len(batch["styles"])]}',
            "response": f'{batch["openers"][(j + i) % len(batch["openers"])]} {spec["cores"][(j * 3 + i) % len(spec["cores"])]} {batch["closers"][(j * 7 + i) % len(batch["closers"])]}',
            "provenance": PROVENANCE,
        }
        if spec.get("runtime"):
            row["generalized_behavioral_lesson"] = True
            row["transformation_provenance"] = "BV_V4_RUNTIME_BOUNDARY_GENERALIZATION_V1"
        rows.append(row)
    return rows

def render(rows):
    return "".join(json.dumps(row, ensure_ascii=False, separators=(",", ":")) + "\n" for row in rows)

def git_blob_sha1(data: bytes) -> str:
    return hashlib.sha1(b"blob " + str(len(data)).encode() + b"\0" + data).hexdigest()

def validate(all_rows):
    ids = [row["record_id"] for row in all_rows]
    pairs = [(row["prompt"], row["response"]) for row in all_rows]
    assert len(all_rows) == 10000
    assert len(ids) == len(set(ids))
    assert len(pairs) == len(set(pairs))
    assert all(row["schema"] == SCHEMA for row in all_rows)
    assert all(row["prompt"] and row["response"] for row in all_rows)
    assert all("blind" not in row["record_id"].lower() for row in all_rows)

def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--output-dir", type=Path)
    args = ap.parse_args()
    all_rows = []
    manifest = {"schema": "VERA_V4_CUSTOM_CORPUS_MANIFEST_V1", "rows": 0, "families": {}}
    for family in CONFIG["specs"]:
        rows = rows_for(family)
        data = render(rows).encode("utf-8")
        all_rows.extend(rows)
        manifest["families"][family] = {
            "rows": len(rows),
            "bytes": len(data),
            "sha256": hashlib.sha256(data).hexdigest(),
            "git_blob_sha1": git_blob_sha1(data),
        }
        if args.output_dir:
            args.output_dir.mkdir(parents=True, exist_ok=True)
            (args.output_dir / f"{family}.jsonl").write_bytes(data)
    validate(all_rows)
    manifest["rows"] = len(all_rows)
    manifest["pair_uniqueness"] = len({(r["prompt"], r["response"]) for r in all_rows})
    manifest["manifest_digest"] = hashlib.sha256(json.dumps(manifest, sort_keys=True, separators=(",", ":")).encode()).hexdigest()
    print(json.dumps(manifest, sort_keys=True))

if __name__ == "__main__":
    main()
